{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "축음기의 원리를 소개한 진술을 진동 변환과 홈 기록이라는 세부 작동 방식으로 풀어 설명한다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "장치를 준비하고 소리를 입력한 뒤 진동을 변환하고 기록하는 단계가 이어진다."
    },
    {
      "id": "R3",
      "type": "CAUSE",
      "otherName": "",
      "reason": "나팔의 진동이 바늘에 전달되어 그 진동 형태에 따른 홈을 실제로 만들어 낸다."
    },
    {
      "id": "R4",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "판에 홈을 만드는 행위가 소리를 저장하기 위한 수단으로 쓰인다."
    },
    {
      "id": "R5",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "과거의 아날로그 기록에서 현재의 디지털 저장으로 시대와 설명 대상이 옮겨 간다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "모든 소리 크기에 균일하게 비트를 할당한다는 설명을 일반적인 할당량인 16비트로 구체화한다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "데이터 양이 많다는 사실을 이유로 오디오 신호를 압축해야 한다는 필요성을 도출한다."
    },
    {
      "id": "R8",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "압축이 필요하다는 문제에 대해 실제로 사용하는 기술인 지각부호화를 제시한다."
    },
    {
      "id": "R9",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지각부호화가 이용하는 청각 특성을 최소가청강도와 차폐라는 구체적인 항목으로 풀어 준다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "감지 가능한 소리 크기의 최솟값이라는 정의에서 그보다 큰 소리는 들린다는 설명이 따라 나온다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "감지 가능한 소리 크기의 최솟값이라는 정의에서 그보다 작은 소리는 들리지 않는다는 판단이 도출된다."
    },
    {
      "id": "R12",
      "type": "CONDITION",
      "otherName": "",
      "reason": "소리 크기가 최소가청강도보다 큰지 작은지에 따라 들리는지 여부가 갈린다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "특정 주파수 범위에서 작은 소리도 들린다는 사례가 최소가청강도의 주파수별 특성을 구체화한다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "저음에서는 더 큰 소리여야 들린다는 사례가 최소가청강도가 주파수에 따라 다름을 보여 준다."
    },
    {
      "id": "R15",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 두 주파수 범위에서 들을 수 있는 소리 크기가 다름을 비교한다."
    },
    {
      "id": "R16",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "청각 특성으로 소개한 차폐를 그 의미와 발생 조건까지 포함하여 자세히 설명한다."
    },
    {
      "id": "R17",
      "type": "CONDITION",
      "otherName": "",
      "reason": "두 소리의 주파수가 가까운지 충분히 떨어져 있는지에 따라 차폐 발생 여부가 갈린다."
    },
    {
      "id": "R18",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "차폐가 가능한 주파수 구간에 임계대역이라는 이름을 붙이고 그 범위를 정의한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주파수에 따라 임계대역 폭이 다르다는 설명을 고음과 저음의 구체적인 폭 차이로 풀어 준다."
    },
    {
      "id": "R20",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "가청 최솟값이라는 공통 기준에서 조용할 때의 최소가청강도와 차폐를 고려한 차폐 문턱값을 구별한다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "청각 특성을 이용한 압축이라는 설명을 문턱값 계산과 비트 할당 및 소리 제거 절차로 구체화한다."
    },
    {
      "id": "R22",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 설명한 임계대역 개념을 실제 오디오 신호를 나누는 단위로 가져다 쓴다."
    },
    {
      "id": "R23",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "최소가청강도라는 청각 원리를 지각부호화의 대역별 차폐 문턱값 산출에 적용한다."
    },
    {
      "id": "R24",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "차폐를 일으키는 소리라는 차폐음의 개념을 실제 압축 과정의 문턱값 산출에 활용한다."
    },
    {
      "id": "R25",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "차폐를 고려한 가청 최솟값이라는 개념을 지각부호화의 각 임계대역에서 실제로 산출한다."
    },
    {
      "id": "R26",
      "type": "PROCESS",
      "otherName": "",
      "reason": "오디오 신호를 임계대역으로 나눈 다음 각 대역의 차폐 문턱값을 구하는 순서이다."
    },
    {
      "id": "R27",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 산출한 차폐 문턱값을 바탕으로 다음 단계의 비트 할당을 진행한다."
    },
    {
      "id": "R28",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "문턱값과의 차이가 큰 소리에 비트를 많이 할당하는 것은 소리 손실을 낮추기 위한 수단이다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "차폐 문턱값보다 작은 소리는 들리지 않는다는 사실이 그 소리를 제거하는 이유가 된다."
    },
    {
      "id": "R30",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "압축 전의 균일한 비트 할당과 지각부호화의 대역별 차등 비트 할당을 비교한다."
    },
    {
      "id": "R31",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "비트 수가 많을수록 원음에 가까워진다는 원리를 지각부호화의 선택적 비트 할당에 적용한다."
    },
    {
      "id": "R32",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "소리별 비트 할당과 손실 저감이라는 세부 설명을 대역별 차등 할당과 품질 저하 최소화라는 일반적 특성으로 종합한다."
    },
    {
      "id": "R33",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "차폐 문턱값 미만 소리의 제거는 감도가 낮은 소리를 제거한다는 지각부호화 설명의 구체적인 구현이다."
    }
  ]
}

